import fs from 'node:fs';import path from 'node:path';import readline from 'node:readline';import {createHash} from 'node:crypto';import {createMicropriceDataset} from '../live-paper/realtime-microprice-dataset.mjs';
const root=path.join(process.env.LOCALAPPDATA,'SigTradingCup/paper-runtime'),sources=JSON.parse(fs.readFileSync('data/realtime-spread-economics-20261005.json')).sources,rows=[],builder=createMicropriceDataset({onSample:r=>rows.push(r)}),started=performance.now();
for(const s of sources){const h=createHash('sha256'),stream=fs.createReadStream(path.join(root,s.file));stream.on('data',b=>h.update(b));for await(const line of readline.createInterface({input:stream,crlfDelay:Infinity}))if(line)builder.consume(JSON.parse(line),{sourceId:s.file});if(h.digest('hex')!==s.sha256)throw Error('SOURCE_HASH_CHANGED');console.log(JSON.stringify({file:s.file,labels:rows.length,elapsedMs:Math.round(performance.now()-started)}));}
const record={schemaVersion:2,frozenAt:new Date().toISOString(),mode:'market_only_causal_microprice_training_dataset',...builder.report(),rows,sources,elapsedMs:performance.now()-started,networkRequests:0,competitionOrders:0,profitabilityEstablished:false};fs.writeFileSync('data/realtime-microprice-dataset-v2-20261005.json',JSON.stringify(record)+'\n',{flag:'wx'});console.log(JSON.stringify({...record,rows:rows.length,sources:sources.length},null,2));
